begin;
do $$
declare owner_id uuid;ids uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];roles text[]:=array['customer','customer','admin','china_driver','china_driver','courier','courier'];i integer;u uuid;cn text:='qa-'||gen_random_uuid();jp text:='qa-'||gen_random_uuid();orders uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];payload jsonb;m jsonb:='[{"weight":2,"length":30,"width":20,"height":10}]';photo text;pid uuid;cancel_pid uuid;denied boolean;n text;count_after integer;
begin
 select id into owner_id from public.kuilu_profiles where role='system_admin' order by created_at limit 1;
 for i in 1..7 loop
  u:=ids[i];insert into auth.users(id,email,raw_app_meta_data)values(u,'qa'||substr(replace(u::text,'-',''),1,20)||'@accounts.kuilu.invalid',jsonb_build_object('kuilu_provisioned',true,'kuilu_username','qa'||substr(replace(u::text,'-',''),1,20),'kuilu_created_by',owner_id,'kuilu_role',roles[i]));
 end loop;set constraints all immediate;
 perform set_config('request.jwt.claim.sub',ids[1]::text,true);execute 'set local role authenticated';
 insert into public.kuilu_addresses(id,country,name,contact,phone,postal,region,street)values(cn,'CN','QA CN','S','000','','CN','Road'),(jp,'JP','QA JP','R','000','','JP','Road');
 payload:=jsonb_build_object('schemaVersion',3,'cargo',jsonb_build_array(jsonb_build_object('name','Sample','packaging','袋子','qty',2,'unitPrice',1,'currency','USD','photos','[]'::jsonb)),'pickupDate','2099-01-01','pickupContact','QA');
 for i in 1..4 loop insert into public.kuilu_orders(id,cn_address_id,jp_address_id,payload,deleted_at,pickup_photos)values(orders[i],cn,jp,payload,now(),'["forged"]');end loop;
 if exists(select 1 from public.kuilu_orders where id=any(orders) and (deleted_at is not null or pickup_photos<>'[]'))then raise exception 'forged fields accepted';end if;
 denied:=false;begin perform public.kuilu_remove_order(orders[1]);exception when others then denied:=true;end;if not denied then raise exception 'customer deleted order';end if;
 denied:=false;begin perform public.kuilu_make_package(orders);exception when others then denied:=true;end;if not denied then raise exception 'customer packed orders';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[3]::text,true);execute 'set local role authenticated';
 perform public.kuilu_remove_order(orders[4]);
 denied:=false;begin perform public.kuilu_edit_order(orders[4],1,'{"pickupNote":"invalid"}');exception when others then denied:=true;end;if not denied then raise exception 'edited deleted order';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[1]::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.kuilu_orders where id=orders[4])then raise exception 'customer sees deleted order';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[3]::text,true);execute 'set local role authenticated';
 perform public.kuilu_remove_order(orders[4],true);
 denied:=false;begin perform public.kuilu_make_package(array[orders[1]]);exception when others then denied:=true;end;if not denied then raise exception 'packed before warehouse';end if;
 perform public.kuilu_order_action(orders[1],'assign',ids[4]);
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[4]::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.kuilu_order_action(orders[1],'pickup',null,m);exception when others then denied:=true;end;if not denied then raise exception 'legacy pickup bypassed photos';end if;
 denied:=false;begin perform public.kuilu_pickup_order(orders[1],m,'[]');exception when others then denied:=true;end;if not denied then raise exception 'empty photos accepted';end if;
 photo:='pickup/'||orders[1]::text||'/'||ids[4]::text||'/'||gen_random_uuid()::text||'.jpg';
 -- Storage metadata fixture only; the entire transaction is rolled back.
 insert into storage.objects(bucket_id,name,metadata)values('kuilu-pickup',photo,'{"mimetype":"image/jpeg","size":100}');
 denied:=false;begin perform public.kuilu_pickup_order(orders[1],m,jsonb_build_array('pickup/'||orders[2]||'/'||ids[4]||'/missing.jpg'));exception when others then denied:=true;end;if not denied then raise exception 'foreign photo accepted';end if;
 perform public.kuilu_pickup_order(orders[1],m,jsonb_build_array(photo));
 if not exists(select 1 from storage.objects where bucket_id='kuilu-pickup' and name=photo)then raise exception 'assigned driver cannot see photo';end if;
 if kuilu_private.can_remove_pickup_photo(photo)then raise exception 'saved proof photo is deletable';end if;
 if not exists(select 1 from storage.objects where name=photo)then raise exception 'saved proof photo deleted';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[5]::text,true);execute 'set local role authenticated';
 if exists(select 1 from storage.objects where name=photo)then raise exception 'other driver sees photo';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[2]::text,true);execute 'set local role authenticated';
 if exists(select 1 from storage.objects where name=photo)then raise exception 'other customer sees photo';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[3]::text,true);execute 'set local role authenticated';
 perform public.kuilu_order_action(orders[1],'receive',null,m);perform public.kuilu_order_action(orders[2],'receive',null,m);perform public.kuilu_order_action(orders[3],'receive',null,m);
 pid:=public.kuilu_make_package(array[orders[1],orders[2]],'QA combined');
 select package_number into n from public.kuilu_packages where id=pid;if n!~'^PKG[0-9]{12}$' then raise exception 'bad package number';end if;
 denied:=false;begin perform public.kuilu_make_package(array[orders[1],orders[3]]);exception when others then denied:=true;end;if not denied then raise exception 'double pack accepted';end if;
 if not exists(select 1 from public.kuilu_orders where id=orders[3] and package_id is null)then raise exception 'failed package not atomic';end if;
 denied:=false;begin perform public.kuilu_remove_order(orders[1]);exception when others then denied:=true;end;if not denied then raise exception 'packed order deleted';end if;
 denied:=false;begin perform public.kuilu_assign_staff(orders[3],'courier',ids[6]);exception when others then denied:=true;end;if not denied then raise exception 'order courier assignment bypass';end if;
 denied:=false;begin perform public.kuilu_package_action(pid,'assign',ids[4]);exception when others then denied:=true;end;if not denied then raise exception 'wrong package role accepted';end if;
 perform public.kuilu_package_action(pid,'assign',ids[6]);
 denied:=false;begin perform public.kuilu_package_action(pid,'unpack');exception when others then denied:=true;end;if not denied then raise exception 'unpacked assigned package';end if;
 cancel_pid:=public.kuilu_make_package(array[orders[3]]);perform public.kuilu_package_action(cancel_pid,'unpack');
 if not exists(select 1 from public.kuilu_orders where id=orders[3] and package_id is null)then raise exception 'unpack did not release order';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[6]::text,true);execute 'set local role authenticated';
 if not exists(select 1 from public.kuilu_packages where id=pid)or(select count(*)from public.kuilu_orders where package_id=pid)<>2 then raise exception 'courier cannot see package contents';end if;
 if not exists(select 1 from storage.objects where name=photo)then raise exception 'courier cannot see pickup proof';end if;
 denied:=false;begin perform public.kuilu_remove_order(orders[1]);exception when others then denied:=true;end;if not denied then raise exception 'courier deleted order';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',ids[7]::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.kuilu_packages where id=pid)or exists(select 1 from public.kuilu_orders where package_id=pid)or exists(select 1 from storage.objects where name=photo)then raise exception 'other courier sees package data';end if;
 execute 'reset role';
end $$;
select 'PASS: recoverable admin-only deletion, mandatory private pickup photos, proof isolation, warehouse-only atomic packaging, courier assignment and package access boundaries' result;
rollback;
